/* ===== UTILS ===== */
const $ = s => document.querySelector(s);
const $$ = s => document.querySelectorAll(s);

/* ===== TOAST ===== */
function showToast(msg, type='info'){
  const c = $('#toastContainer');
  const t = document.createElement('div');
  t.className = 'toast toast-'+type;
  t.textContent = msg;
  c.appendChild(t);
  requestAnimationFrame(()=>t.classList.add('show'));
  setTimeout(()=>{t.classList.remove('show');setTimeout(()=>t.remove(),400);},4000);
}

/* ===== NAVBAR SCROLL ===== */
function handleNavScroll(){
  const nav = $('.navbar');
  if(window.scrollY > 80) nav.classList.add('scrolled');
  else nav.classList.remove('scrolled');
}

/* ===== ACTIVE NAV ===== */
function updateActiveNav(){
  const sections = $$('section[id]');
  const links = $$('.nav-links a');
  let current = '';
  sections.forEach(s=>{
    if(window.scrollY >= s.offsetTop - 200) current = s.id;
  });
  links.forEach(a=>{
    a.classList.remove('active');
    if(a.getAttribute('href') === '#'+current) a.classList.add('active');
  });
}

/* ===== SCROLL REVEAL ===== */
function initReveal(){
  const obs = new IntersectionObserver((entries)=>{
    entries.forEach(e=>{
      if(e.isIntersecting){e.target.classList.add('revealed');obs.unobserve(e.target);}
    });
  },{threshold:0.1});
  $$('.reveal').forEach(el=>obs.observe(el));
}

/* ===== FAQ ACCORDION ===== */
function initFAQ(){
  $$('.faq-item').forEach(item=>{
    item.querySelector('.faq-q').addEventListener('click',()=>{
      const isOpen = item.classList.contains('open');
      $$('.faq-item').forEach(i=>i.classList.remove('open'));
      if(!isOpen) item.classList.add('open');
    });
  });
}

/* ===== ARTIST MODAL ===== */
function initArtistModal(){
  const modal = $('#artistModal');
  const overlay = modal.querySelector('.modal-overlay');
  $$('.artist-card').forEach(card=>{
    card.querySelector('.artist-btn').addEventListener('click',()=>{
      const i = card.dataset.index;
      const a = artistsData[i];
      modal.querySelector('.modal-body h2').textContent = a.name;
      modal.querySelector('.modal-body .modal-role').textContent = a.role;
      modal.querySelector('.modal-body .modal-img').src = a.image;
      modal.querySelector('.modal-body .modal-bio').textContent = a.bio;
      modal.querySelector('.modal-body .modal-session').textContent = 'Session: '+a.session;
      modal.classList.add('open');
      document.body.style.overflow = 'hidden';
    });
  });
  function close(){modal.classList.remove('open');document.body.style.overflow='';}
  overlay.addEventListener('click',close);
  modal.querySelector('.modal-close').addEventListener('click',close);
  document.addEventListener('keydown',e=>{if(e.key==='Escape')close();});
}

/* ===== TICKET MODAL ===== */
function initTicketModal(){
  const modal = $('#ticketModal');
  const overlay = modal.querySelector('.modal-overlay');
  const form = $('#ticketForm');
  const countInput = $('#ticketCount');
  const nameInput = $('#ticketName');
  const emailInput = $('#ticketEmail');
  let selectedTier = null;

  $$('.tier-card').forEach(card=>{
    card.querySelector('.tier-btn').addEventListener('click',()=>{
      selectedTier = card.dataset.tier;
      const tier = ticketTiers.find(t=>t.id===selectedTier);
      $('#ticketModalTitle').textContent = 'Complete Your Order';
      $('#ticketModalTier').textContent = tier.name + ' — €'+tier.price;
      countInput.value = 1;
      updateTicketTotal();
      modal.classList.add('open');
      document.body.style.overflow = 'hidden';
    });
  });

  function updateTicketTotal(){
    const tier = ticketTiers.find(t=>t.id===selectedTier);
    const count = parseInt(countInput.value)||1;
    $('#ticketTotal').textContent = '€'+(tier.price*count);
  }
  countInput.addEventListener('input',updateTicketTotal);

  function close(){modal.classList.remove('open');document.body.style.overflow='';}
  overlay.addEventListener('click',close);
  modal.querySelector('.modal-close').addEventListener('click',close);
  document.addEventListener('keydown',e=>{if(e.key==='Escape')close();});

  form.addEventListener('submit',e=>{
    e.preventDefault();
    let valid = true;
    [nameInput,emailInput].forEach(i=>i.classList.remove('error'));
    if(!nameInput.value.trim()){nameInput.classList.add('error');valid=false;}
    if(!emailInput.value.trim()||!emailInput.value.includes('@')){emailInput.classList.add('error');valid=false;}
    if(!$('#ticketTerms').checked) valid=false;
    if(!valid){showToast('Please fill in all fields correctly.','error');return;}
    close();
    showToast('Reservation confirmed! Check your email for details.','success');
  });
}

const ticketTiers = [
  {id:'night',name:'Night Pass',price:29,features:['Entry after 19:00','Main exhibition access','Full program access']},
  {id:'curator',name:'Curator Pass',price:59,features:['Everything in Night Pass','Hidden collection tour','Reserved artist talk seating']},
  {id:'patron',name:'Patron Pass',price:129,features:['Everything in Curator Pass','VIP lounge access','Signed event print','Priority entrance']}
];

/* ===== CALENDAR ===== */
function saveToCalendar(){
  const ics = [
    'BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//ARTIFACT//Museum Night//EN',
    'BEGIN:VEVENT',
    'UID:artifact-museum-night-2026@oldgallery.pl',
    'DTSTART:20261018T190000',
    'DTEND:20261019T020000',
    'SUMMARY:ARTIFACT: Museum Night',
    'DESCRIPTION:A cinematic after-hours museum event with exhibitions, performances, talks, and guided tours.',
    'LOCATION:The Old Gallery, Warsaw',
    'END:VEVENT','END:VCALENDAR'
  ].join('\r\n');
  const blob = new Blob([ics],{type:'text/calendar;charset=utf-8'});
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;a.download = 'artifact-museum-night.ics';
  document.body.appendChild(a);a.click();document.body.removeChild(a);
  URL.revokeObjectURL(url);
  showToast('Calendar event saved!','success');
}

/* ===== NEWSLETTER ===== */
function initNewsletter(){
  const form = $('#newsletterForm');
  const input = $('#newsletterEmail');
  form.addEventListener('submit',e=>{
    e.preventDefault();
    if(!input.value.trim()||!input.value.includes('@')){showToast('Please enter a valid email.','error');return;}
    showToast('Welcome! You are now on the list.','success');
    input.value = '';
  });
}

/* ===== MOBILE MENU ===== */
function initMobileMenu(){
  const hamburger = $('.hamburger');
  const links = $('.nav-links');
  hamburger.addEventListener('click',()=>{
    hamburger.classList.toggle('open');
    links.classList.toggle('open');
  });
}

/* ===== INIT ===== */
document.addEventListener('DOMContentLoaded',()=>{
  handleNavScroll();
  updateActiveNav();
  initReveal();
  initFAQ();
  initArtistModal();
  initTicketModal();
  initNewsletter();
  initMobileMenu();
  window.addEventListener('scroll',()=>{handleNavScroll();updateActiveNav();});
});"}

